ST.xhtml:
IF Mode<>1 AND Servo.bEnabled AND SERVO.bHomed THEN    //没有在自动运行模式下，伺服使能
	//示教点位
	FOR i:=1 TO 10  DO
		IF HMI_Servo.write[i] THEN
		HMI_Servo.position[i]:=Servo.fActPos;
		END_IF
		//运动执行
		IF HMI_Servo.execute[i] THEN
			Servo.fAbsTarget:= HMI_Servo.position[i];
			Servo.xMoveAbs:=TRUE;
		END_IF
		//执行完毕复位
		IF Servo.bAbMoveDone OR Servo.bError  THEN
			Servo.xMoveAbs:=FALSE;
		END_IF
	END_FOR

END_IF

//轴使能 MC_Power( Axis:=AXIS , Enable:= TRUE , bRegulatorOn:= xEnable , bDriveStart:=TRUE , Status=> bEnabled , bRegulatorRealState=> , bDriveStartRealState=> , Busy=> , Error=> , ErrorID=> ); //轴回零 MC_Home( Axis:= AXIS, Execute:= xHome , Position:= , Done=> bHomed , Busy=> bHoming , CommandAborted=> , Error=> , ErrorID=> );
//轴复位 MC_Reset(Axis:=AXIS , Execute:= XReset , Done=> , Busy=> , Error=> , ErrorID=> ); //轴jog MC_Jog( Axis:=AXIS, JogForward:=xJogPos , JogBackward:=xJogNeg , Velocity:=fJogVel , Acceleration:= fAcc , Deceleration:=fDec , Jerk:= , Busy=> , CommandAborted=> , Error=> , ErrorId=> ); //轴停止 MC_Halt( Axis:=AXIS, Execute:=xStop , Deceleration:= fDec , Jerk:= , Done=> , Busy=> , CommandAborted=> , Error=> , ErrorID=> ); //轴绝对运动 MC_MoveAbsolute( Axis:=AXIS, Execute:= xMoveAbs , Position:= fAbsTarget , Velocity:=fVelocity , Acceleration:= fAcc , Deceleration:= fDec , Jerk:= , Direction:= , ////BufferMode:= , Done=> bAbMoveDone , Busy=> bMoving , ////Active=> , CommandAborted=> , Error=> , ErrorID=> ); //轴相对运动 MC_MoveRelative( Axis:=AXIS , Execute:=xMoveRel , Distance:=fRelTarget , Velocity:= fVelocity , Acceleration:= fAcc , Deceleration:= fDec , Jerk:= , ////BufferMode:= , Done=> bReMoveDone, Busy=> , ////Active=> , CommandAborted=> , Error=> , ErrorID=> );
fActPos:=AXIS.fActPosition ; //当前位置 fActVel:=AXIS.fActVelocity ; //当前速度 bError:=MC_Power.Error OR MC_Home.Error OR MC_MoveAbsolute.Error OR MC_MoveAbsolute.Error OR MC_Halt.Error OR MC_Jog.Error OR MC_Reset.Error OR AXIS.nAxisState=1 OR AXIS.nAxisState=2 ; iErrorCode:=MC_Power.ErrorID OR MC_Home.ErrorID OR MC_MoveAbsolute.ErrorID OR MC_MoveAbsolute.ErrorID OR MC_Halt.ErrorID OR MC_Jog.ErrorId OR MC_Reset.ErrorID ;

CASE cylinder_type OF
	0:     //单控电池阀
		//命令逻辑选择
		IF xManualAuto  THEN
			//自动模式，使用自动命令
			bEnableCmd1 :=xAutoExtend;
			ELSE
			//手动模式，使用手动命令
			bEnableCmd1 :=xManualExtend  ;
		END_IF
		//控制指令
		IF bEnableCmd1 THEN
			//开始伸出
			yValve1:=TRUE;
			ELSE
			//开始缩回
			yValve1 :=FALSE;
		END_IF


			tActionTimer(IN := (NOT xPosExtend AND NOT yValve1)  OR   (NOT xPosRetract AND yValve1), PT:=tTimeout );
			bAlarm :=tActionTimer .Q;

	1:        //双控电池阀
		//命令逻辑选择
		IF xManualAuto  THEN
			//自动模式，使用自动命令
			bEnableCmd1 :=xAutoExtend;
			bEnableCmd2 :=xAutoRetract;
		ELSE
			//手动模式，使用手动命令
			bEnableCmd1 :=xManualExtend;
			bEnableCmd2 :=xManualRetract;
		END_IF
		//伸出控制指令
		IF bEnableCmd1 THEN
			//开始伸出
			yValve1:=TRUE;
			yValve2:=FALSE;
		ELSE 
			yValve1:=FALSE;
		END_IF

		IF bEnableCmd2 THEN
			//开始缩回
			yValve2:=TRUE;
			yValve1:=FALSE;
		ELSE 
			yValve2:=FALSE;
		END_IF

			tActionTimer(IN := (NOT xPosExtend AND NOT yValve1)  OR   (NOT xPosRetract AND yValve2), PT:=tTimeout );
			bAlarm :=tActionTimer .Q;

END_CASE

IF xReset THEN
	bAlarm:=FALSE ;
END_IF

//倍率指定
IF Speed_X1  THEN
	iDenominator:=100;
ELSIF Speed_X10 THEN
	iDenominator:=10;
ELSIF Speed_X100 THEN 
    iDenominator:=1;
END_IF
