Error :=MC_GearIn_1.Error OR MC_GearIn_2.Error OR MC_GearIn_3.Error OR MC_GearIn_4.Error OR MC_GearIn_5.Error OR MC_GearIn_6.Error OR MC_GearIn_7.Error OR MC_GearIn_8.Error OR MC_GearIn_9.Error ;  
ErrorID :=MC_GearIn_1.ErrorID OR MC_GearIn_2.ErrorID OR MC_GearIn_3.ErrorID OR MC_GearIn_4.ErrorID OR MC_GearIn_5.ErrorID OR MC_GearIn_6.ErrorID OR MC_GearIn_7.ErrorID OR MC_GearIn_8.ErrorID OR MC_GearIn_9.ErrorID ;  

//1轴断开齿合
MC_GearOut_1(Slave:=AXIS_1 , Execute:= F_TRIG_1.Q AND MC_GearIn_1.InGear , Done=> xStop_1 , Busy=> , Error=> , ErrorID=> );

//2轴断开齿合
MC_GearOut_2(Slave:=AXIS_2 , Execute:= F_TRIG_2.Q AND MC_GearIn_2.InGear , Done=> xStop_2 , Busy=> , Error=> , ErrorID=> );

//3轴断开齿合
MC_GearOut_3(Slave:=AXIS_3 , Execute:= F_TRIG_3.Q AND MC_GearIn_3.InGear , Done=> xStop_3 , Busy=> , Error=> , ErrorID=> );


