//9轴断开齿合
MC_GearOut_9(Slave:=AXIS_9 , Execute:= F_TRIG_9.Q AND MC_GearIn_9.InGear , Done=> xStop_9 , Busy=> , Error=> , ErrorID=> );

(* ================= 报警优先 ================= *)
IF RobotAlarm THEN
    State := 4;
END_IF

CASE State OF

    (* -------- 0：空闲 -------- *)
    0:
        StartOut := FALSE;
        StopOut  := TRUE;
        PauseOut := FALSE;
		ResetOut:=FALSE;
        IF StartCmd AND NOT RobotAlarm THEN
            State := 1;
        END_IF

    (* -------- 1：运行 -------- *)
    1:
		IF NOT PowerOn THEN
			PowerOnOut:=TRUE;
		ELSE
			PowerOnOut:=FALSE;
		END_IF
		IF PowerOn THEN
			StartOut := TRUE;
			StopOut  := FALSE;
			PauseOut := FALSE;
		END_IF


        IF StopCmd THEN
            State := 3;
        ELSIF PauseCmd THEN
            State := 2;

        END_IF

    (* -------- 2：暂停 -------- *)
    2:
        PauseOut := TRUE;
		StartOut := FALSE ;
        StopOut  := FALSE;
        IF StopCmd THEN
            State := 3;
        ELSIF  StartCmd AND NOT RobotAlarm THEN
            State := 1;
        END_IF

    (* -------- 3：停止 -------- *)
    3:
        StartOut := FALSE;
        StopOut  := TRUE;
        PauseOut := FALSE;

        IF RobotStopped THEN
            State := 0;
        END_IF

    (* -------- 4：报警 -------- *)
    4:
        StartOut := FALSE;
        StopOut  := TRUE;
        PauseOut := FALSE;

        IF  Reset THEN
			ResetOut:=TRUE;
            State := 0;
        END_IF

END_CASE

(* ================= 状态输出 ================= *)
StatusRun   := (State = 1);
StatusPause := (State = 2);
StatusStop  := (State = 0) OR (State = 3);
StatusAlarm := (State = 4);

// 模式状态
bAuto := xAutoMode;

// 状态机
CASE iDeviceState OF
    EN_功能块状态.停止:  // 停止状态
        IF NOT xEmergency THEN
            iDeviceState := EN_功能块状态.急停;  // 急停
            bEmergencyActive := TRUE;
        ELSIF xFault THEN
            iDeviceState := EN_功能块状态.故障;  // 故障
            bBuzzerActive := TRUE;
        ELSIF (bAuto AND xStart)  THEN
		 bBeepOnce := TRUE;  // 启动短鸣
		  iDeviceState := EN_功能块状态.初始化;  // 初始化

        END_IF;

    EN_功能块状态.运行:  // 运行状态
        IF NOT xEmergency THEN
            iDeviceState := EN_功能块状态.急停;  // 急停
            bEmergencyActive := TRUE;
        ELSIF xFault THEN
            iDeviceState := EN_功能块状态.故障;  // 故障
            bBuzzerActive := TRUE;
        ELSIF xStop THEN
            iDeviceState := EN_功能块状态.停止;  // 停止
            bBeepOnce := TRUE;  // 停止短鸣
        END_IF;

    EN_功能块状态.故障:  // 故障状态
        IF NOT xEmergency THEN
            iDeviceState := EN_功能块状态.急停;  // 急停
            bEmergencyActive := TRUE;
        ELSIF xReset AND NOT xFault THEN
            iDeviceState := EN_功能块状态.停止;  // 停止
            bBuzzerActive := FALSE;
			bBuzzer:=FALSE;
        END_IF;

    EN_功能块状态.急停:  // 急停状态
        // 急停复位需要：急停信号解除 + 复位按钮按下
        IF  xEmergency AND xReset THEN
            iDeviceState := EN_功能块状态.停止;  // 停止
            bEmergencyActive := FALSE;
            bEmergencyBuzzer := FALSE;
			bBuzzer:=FALSE;
        END_IF;
	EN_功能块状态.初始化:  //初始化状态
	 TON_0(IN:=TRUE , PT:=T#3S );
		IF TON_0.Q THEN
		iDeviceState := EN_功能块状态.运行;  // 运行
		END_IF 
END_CASE;

// 急停蜂鸣器控制（急停时蜂鸣器以不同频率鸣响）
IF  bEmergencyActive THEN
    tEmergencyBeep(IN := NOT tEmergencyBeep.Q, PT := T#2S );
	ALT_1(xExecute:= tEmergencyBeep.Q, xOut:=bBuzzer );  // 急停时蜂鸣器响2秒，停2秒	
END_IF;

//三色灯控制
// 闪烁定时器
tFlashTimer(IN := NOT tFlashTimer.Q, PT := T#500MS);
ALT_0(xExecute:=tFlashTimer.Q , xOut:=bFlashFlag );

CASE iDeviceState OF
    EN_功能块状态.停止:  // 停止状态
        IF bAuto THEN
            bYellow := TRUE;           // 自动模式：黄灯常亮
        ELSE
            bYellow := bFlashFlag;     // 手动模式：黄灯闪烁
        END_IF;
		 bGreen :=FALSE;
		 bRed :=FALSE;

    EN_功能块状态.运行:  // 运行状态
        bGreen := TRUE;
         bRed :=FALSE;
		  bYellow := FALSE; 
    EN_功能块状态.故障:  // 故障状态
        bRed := TRUE;
         bGreen :=FALSE;
		 bYellow := FALSE; 
    EN_功能块状态.急停:  // 急停状态
        bRed := bFlashFlag;  // 红灯闪烁
		bGreen :=FALSE;
		 bYellow := FALSE; 
END_CASE;
tShortBeep(IN := bBeepOnce AND NOT bEmergencyActive, PT := T#500MS);
// 蜂鸣器控制
IF bBeepOnce AND NOT bEmergencyActive THEN
	bBuzzer := TRUE;  // 短鸣
    IF tShortBeep.Q THEN
        bBeepOnce := FALSE;
       bBuzzer := FALSE;
    END_IF;

END_IF;

// 故障时蜂鸣器（非急停状态时生效）
IF NOT bEmergencyActive AND xFault  THEN
    tBuzzerPulse(IN := NOT tBuzzerPulse.Q, PT := T#500MS);
ALT_2(xExecute:= tBuzzerPulse.Q, xOut:= bBuzzer);
END_IF;


//蜂鸣器5S后停止
TON_2(IN:=iDeviceState=2 OR iDeviceState=3 OR bWarning_alarm ,PT:=T#5S);
IF TON_2.Q THEN
	bBuzzer:=FALSE;
END_IF

IF bWarning_alarm AND NOT TON_2.Q THEN
	bBuzzer:=TRUE;

END_IF
IF bWarning_alarm  THEN
	 bRed := TRUE;

END_IF

IF xReset THEN
	bBuzzer:=FALSE;
	bRed := FALSE;
END_IF



// 输出状态
iState := iDeviceState;
